	@Test
	void materializedBulkReadsValidateRunAndDestinationRanges() throws Exception {
		commit(() -> {
			addQuiet(S1, P1, O1);
			addQuiet(S1, P1, uri(12));
		});
		assertThat(store.buildNowForTest()).isTrue();

		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			NativeLmdbQuerySource.NativeAdjacency adjacency = store.adjacency(view, P1, true, true);
			long run = adjacency.find(S1);
			assertThat(adjacency.neighborAt(run, 0)).isEqualTo(O1);

			assertThatThrownBy(() -> adjacency.copyNeighbors(run, -1, 1, new long[1], 0))
					.isInstanceOf(IllegalArgumentException.class);
			assertThatThrownBy(() -> adjacency.copyNeighbors(run, 3, 1, new long[1], 0))
					.isInstanceOf(IllegalArgumentException.class);
			assertThatThrownBy(() -> adjacency.copyNeighbors(run, 0, -1, new long[1], 0))
					.isInstanceOf(IllegalArgumentException.class);
			assertThatThrownBy(() -> adjacency.copyNeighbors(run, 0, 2, new long[1], 0))
					.isInstanceOf(IllegalArgumentException.class);
			assertThatThrownBy(() -> adjacency.copyNeighbors(run, 0, 1, new long[1], -1))
					.isInstanceOf(IllegalArgumentException.class);
			assertThatThrownBy(() -> adjacency.copyContexts(run, 0, 2, new long[1], 0))
					.isInstanceOf(IllegalArgumentException.class);
		}
	}

	@Test
	void supernodeGroupUpdatesKeepSnapshotsExact() throws Exception {
		// the bulk load overflows the commit collector by design; the subsequent build clears the gap
		commit(() -> {
			for (long i = 0; i < SUPERNODE_EDGES; i++) {
				addQuiet(S1, P1, FIRST_NEIGHBOR + i);
			}
		});
		assertThat(store.buildNowForTest()).isTrue();
		long r0 = tripleStore.getDataRevision();

		try (LmdbAdjacencyReadView view = store.acquire(r0)) {
			assertThat(view.isExact()).isTrue();
			assertThat(store.tryCount(view, S1, P1, -1, -1, true)).isEqualTo(SUPERNODE_EDGES);
			NativeLmdbQuerySource.NativeAdjacency adjacency = store.adjacency(view, P1, true, true);
			assertThat(adjacency).isNotNull();
			long run = adjacency.find(S1);
			assertThat(run).isPositive();
			assertThat(adjacency.size(run)).isEqualTo(SUPERNODE_EDGES);
			assertThat(adjacency.neighborAt(run, 0)).isEqualTo(FIRST_NEIGHBOR);
			assertThat(adjacency.neighborAt(run, SUPERNODE_EDGES - 1))
					.isEqualTo(FIRST_NEIGHBOR + SUPERNODE_EDGES - 1);
			// bounded int batch copy across a chunk boundary
			long[] batch = new long[512];
			int copied = adjacency.copyNeighbors(run, LmdbAdjacencyRunCodec.BLOCK_FOR_MAX_EDGES - 256, 512, batch, 0);
			assertThat(copied).isEqualTo(512);
			assertThat(batch[0]).isEqualTo(FIRST_NEIGHBOR + LmdbAdjacencyRunCodec.BLOCK_FOR_MAX_EDGES - 256);
			assertThat(batch[511]).isEqualTo(FIRST_NEIGHBOR + LmdbAdjacencyRunCodec.BLOCK_FOR_MAX_EDGES + 255);
			assertThat(adjacency.lowerBound(run, 0, FIRST_NEIGHBOR + 777, 0)).isEqualTo(777);
			assertKeys(adjacency, S1);
			assertThat(adjacency.runsNeighborOrdered()).isTrue();
		}

		// updates in the first, middle, and last chunk range plus one appended neighbor
		long middle = FIRST_NEIGHBOR + SUPERNODE_EDGES / 2;
		long last = FIRST_NEIGHBOR + SUPERNODE_EDGES - 1;
		commit(() -> {
			removeQuiet(S1, P1, FIRST_NEIGHBOR);
			removeQuiet(S1, P1, middle);
			removeQuiet(S1, P1, last);
			addQuiet(S1, P1, last + 1000);
		});
		long r1 = tripleStore.getDataRevision();

		try (LmdbAdjacencyReadView oldView = store.acquire(r0);
				LmdbAdjacencyReadView newView = store.acquire(r1)) {
			assertThat(oldView.isExact()).isTrue();
			assertThat(newView.isExact()).isTrue();
			// snapshot before the chunk replacement
			assertThat(store.tryCount(oldView, S1, P1, -1, -1, true)).isEqualTo(SUPERNODE_EDGES);
			assertThat(store.tryHas(oldView, S1, P1, FIRST_NEIGHBOR, -1, true)).isEqualTo(1);
			// snapshot after
			assertThat(store.tryCount(newView, S1, P1, -1, -1, true)).isEqualTo(SUPERNODE_EDGES - 2);
			assertThat(store.tryHas(newView, S1, P1, FIRST_NEIGHBOR, -1, true)).isZero();
			assertThat(store.tryHas(newView, S1, P1, middle, -1, true)).isZero();
			assertThat(store.tryHas(newView, S1, P1, last, -1, true)).isZero();
			assertThat(store.tryHas(newView, S1, P1, last + 1000, -1, true)).isEqualTo(1);
			NativeLmdbQuerySource.NativeAdjacency adjacency = store.adjacency(newView, P1, true, true);
			assertThat(adjacency).isNotNull();
			long run = adjacency.find(S1);
			assertThat(adjacency.size(run)).isEqualTo(SUPERNODE_EDGES - 2);
			assertThat(adjacency.neighborAt(run, 0)).isEqualTo(FIRST_NEIGHBOR + 1);
			assertThat(adjacency.neighborAt(run, SUPERNODE_EDGES - 3)).isEqualTo(last + 1000);
		}
	}

	@Test
	void incomingCommonTypeRowSharesAcrossSuccessiveSnapshots() throws Exception {
		commit(() -> {
			for (long i = 0; i < SUPERNODE_EDGES; i++) {
				addQuiet(FIRST_NEIGHBOR + i, P1, O1);
			}
		});
		assertThat(store.buildNowForTest()).isTrue();
		long r0 = tripleStore.getDataRevision();
		long middle = FIRST_NEIGHBOR + SUPERNODE_EDGES / 2;
		long appended = FIRST_NEIGHBOR + SUPERNODE_EDGES + 1000;

		commit(() -> {
			removeQuiet(middle, P1, O1);
			addQuiet(appended, P1, O1);
		});
		long r1 = tripleStore.getDataRevision();
		long secondRemoved = FIRST_NEIGHBOR + 1;
		long secondAppended = appended + 1000;
		commit(() -> {
			removeQuiet(secondRemoved, P1, O1);
			addQuiet(secondAppended, P1, O1);
		});
		long r2 = tripleStore.getDataRevision();

		try (LmdbAdjacencyReadView original = store.acquire(r0);
				LmdbAdjacencyReadView first = store.acquire(r1);
				LmdbAdjacencyReadView second = store.acquire(r2)) {
			NativeLmdbQuerySource.NativeAdjacency originalIncoming = store.adjacency(original, P1, false, true);
			NativeLmdbQuerySource.NativeAdjacency firstIncoming = store.adjacency(first, P1, false, true);
			NativeLmdbQuerySource.NativeAdjacency secondIncoming = store.adjacency(second, P1, false, true);
			long originalRun = originalIncoming.find(O1);
			long firstRun = firstIncoming.find(O1);
			long secondRun = secondIncoming.find(O1);

			assertThat(originalIncoming.size(originalRun)).isEqualTo(SUPERNODE_EDGES);
			assertThat(originalIncoming.lowerBound(originalRun, 0, middle, 0)).isEqualTo(SUPERNODE_EDGES / 2);
			assertThat(firstIncoming.size(firstRun)).isEqualTo(SUPERNODE_EDGES);
			assertThat(firstIncoming.lowerBound(firstRun, 0, middle, 0)).isEqualTo(SUPERNODE_EDGES / 2);
			assertThat(firstIncoming.neighborAt(firstRun, SUPERNODE_EDGES / 2)).isEqualTo(middle + 1);
			assertThat(firstIncoming.neighborAt(firstRun, SUPERNODE_EDGES - 1)).isEqualTo(appended);
			assertThat(secondIncoming.size(secondRun)).isEqualTo(SUPERNODE_EDGES);
			assertThat(secondIncoming.neighborAt(secondRun, 0)).isEqualTo(FIRST_NEIGHBOR);
			assertThat(secondIncoming.neighborAt(secondRun, 1)).isEqualTo(FIRST_NEIGHBOR + 2);
			assertThat(secondIncoming.neighborAt(secondRun, SUPERNODE_EDGES - 1)).isEqualTo(secondAppended);
		}
		LmdbAdjacencyMetrics.Snapshot metrics = store.snapshotMetrics();
		assertThat(metrics.structurallySharedRows).isGreaterThanOrEqualTo(2);
		assertThat(metrics.reusedLeaves).isPositive();
		assertThat(metrics.rewrittenLeaves).isPositive();
		assertThat(metrics.decodedRepairPairs).isLessThanOrEqualTo(8 * optionsChunkEdges() + 4);
		assertThat(metrics.encodedRepairPairs).isLessThanOrEqualTo(8 * optionsChunkEdges() + 4);
	}

	private long optionsChunkEdges() {
		return Math.min(options.supernodeChunkEdges(), options.supernodeTargetBytes() / (Long.BYTES * 2));
	}

	@Test
	void kernelDeclinesDuringPendingWindowAndServesAfterApply() throws Exception {
		commit(() -> {
			addQuiet(S1, P1, O1);
			addQuiet(S2, P1, O1);
		});
		assertThat(store.buildNowForTest()).isTrue();

		store.pauseApplierForTest(true);
		try {
			tripleStore.startTransaction();
			addQuiet(S1, P1, uri(12));
			tripleStore.commit();
			store.applyCommitted(tripleStore.drainDirectAdjacencyCommitDelta());
			long r1 = tripleStore.getDataRevision();
			try (LmdbAdjacencyReadView view = store.acquire(r1)) {
				assertThat(view.isExact()).isTrue();
				long declineBefore = store.snapshotMetrics()
						.fallbacks(FallbackReason.KERNEL_REQUIRES_COMPLETE_REVISION);
				assertThat(store.adjacency(view, P1, true, true)).isNull();
				assertThat(store.snapshotMetrics().fallbacks(FallbackReason.KERNEL_REQUIRES_COMPLETE_REVISION))
						.isGreaterThan(declineBefore);
			}
		} finally {
			store.pauseApplierForTest(false);
		}
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			NativeLmdbQuerySource.NativeAdjacency adjacency = store.adjacency(view, P1, true, true);
			assertThat(adjacency).isNotNull();
			long run = adjacency.find(S1);
			assertThat(adjacency.size(run)).isEqualTo(2);
			// the generation-backed run and the base-backed run resolve through their own catalogs
			long baseRun = adjacency.find(S2);
			assertThat(adjacency.size(baseRun)).isEqualTo(1);
			assertThat(adjacency.find(uri(999))).isEqualTo(NativeLmdbQuerySource.NativeAdjacency.NOT_FOUND);
		}
	}

	@Test
	void keyEnumerationMergesBaseInsertAndTombstoneBySnapshot() throws Exception {
		commit(() -> {
			addQuiet(S1, P1, O1);
			addQuiet(S2, P1, O1);
		});
		assertThat(store.buildNowForTest()).isTrue();
		long r0 = tripleStore.getDataRevision();

		commit(() -> {
			removeQuiet(S1, P1, O1);
			addQuiet(S3, P1, O1);
		});
		long r1 = tripleStore.getDataRevision();

		try (LmdbAdjacencyReadView oldView = store.acquire(r0);
				LmdbAdjacencyReadView newView = store.acquire(r1)) {
			assertKeys(store.adjacency(oldView, P1, true, true), S1, S2);
			assertKeys(store.adjacency(newView, P1, true, true), S2, S3);
		}
	}

	private static void assertKeys(NativeLmdbQuerySource.NativeAdjacency adjacency, long... expected) {
		assertThat(adjacency).isNotNull();
		assertThat(adjacency.supportsKeyEnumeration()).isTrue();
		assertThat(adjacency.keyCount()).isEqualTo(expected.length);
		for (int i = 0; i < expected.length; i++) {
			assertThat(adjacency.keyAt(i)).isEqualTo(expected[i]);
		}
	}
